import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.TreeSet;

public class Drill {
    static String run() {
        TreeMap<Integer, String> tm = new TreeMap<>();
        tm.put(5, "e");
        tm.put(1, "a");
        tm.put(9, "i");
        int lo = tm.firstKey();
        int hi = tm.lastKey();
        Integer f = tm.floorKey(6);
        Integer c = tm.ceilingKey(6);
        @@BLANK@@
        Integer hg = tm.higherKey(5);
        Map.Entry<Integer, String> p = tm.pollFirstEntry();
        TreeSet<Integer> ts = new TreeSet<>(List.of(5, 1, 9));
        Integer tf = ts.floor(6);
        Integer tc = ts.ceiling(6);
        int tfi = ts.first();
        int tp = ts.pollFirst();
        return lo + " " + hi + " " + f + " " + c + " " + lw + " " + hg + " " + p.getValue() + " " + tm.size()
                + " " + tf + " " + tc + " " + tfi + " " + tp + " " + ts.size();
    }

    static int bad = 0;
    static void check(Object got, Object exp) {
        String g = String.valueOf(got), e = String.valueOf(exp);
        if (!g.equals(e)) { bad++; System.out.println("FAIL: got " + g + " expected " + e); }
    }
    static void done() { if (bad == 0) System.out.println("PASS"); }

    public static void main(String[] args) {
        check(run(), "1 9 5 9 1 9 a 2 5 9 1 1 2");
        done();
    }
}
